dashboard.definition:
{
  "title": "Work Process Performance",
  "description": "SAP ABAP work process utilization, dispatcher health, and function-level activity",
  "inputs": {
    "input_global_trp": {
      "options": {
        "defaultValue": "-30d@d,now",
        "token": "global_time"
      },
      "title": "Global Time Range",
      "type": "input.timerange"
    },
    "input_nav_dropdown": {
      "type": "input.dropdown",
      "title": "Navigate to Dashboard",
      "options": {
        "items": [
          {
            "label": "Overview",
            "value": "logserv_overview"
          },
          {
            "label": "Environment Health",
            "value": "logserv_environment_health"
          },
          {
            "label": "ABAP Security",
            "value": "logserv_abap_security"
          },
          {
            "label": "ABAP Operations",
            "value": "logserv_abap_operations"
          },
          {
            "label": "HANA Audit",
            "value": "logserv_hana_audit"
          },
          {
            "label": "HANA Trace",
            "value": "logserv_hana_trace"
          },
          {
            "label": "SAP Services",
            "value": "logserv_sap_services"
          },
          {
            "label": "Cloud Connector",
            "value": "logserv_cloud_connector"
          },
          {
            "label": "Web Dispatcher",
            "value": "logserv_web_dispatcher"
          },
          {
            "label": "Web and API Performance",
            "value": "logserv_web_api_performance"
          },
          {
            "label": "Network Perimeter",
            "value": "logserv_network_perimeter"
          },
          {
            "label": "DNS Analytics",
            "value": "logserv_dns_analytics"
          },
          {
            "label": "Linux",
            "value": "logserv_linux"
          },
          {
            "label": "Windows",
            "value": "logserv_windows"
          },
          {
            "label": "Proxy",
            "value": "logserv_proxy"
          },
          {
            "label": "Host Details",
            "value": "logserv_host_details"
          },
          {
            "label": "Cross-Stack Authentication",
            "value": "logserv_cross_stack_authentication"
          },
          {
            "label": "Change & Configuration Activity",
            "value": "logserv_change_config"
          },
          {
            "label": "SAP Router",
            "value": "logserv_sap_router"
          }
        ],
        "token": "nav_target"
      }
    }
  },
  "visualizations": {
    "viz_rect_kpi_total": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_kpi_sids": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_kpi_errors": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_kpi_functions": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_category_trend": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_category_mix": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_top_functions": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_severity_trend": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_by_sid": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_rect_recent_errors": {
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      },
      "type": "splunk.rectangle"
    },
    "viz_kpi_total": {
      "dataSources": {
        "primary": "ds_wp_total"
      },
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      },
      "title": "Total WP Events",
      "type": "splunk.singlevalue"
    },
    "viz_kpi_sids": {
      "dataSources": {
        "primary": "ds_wp_sids"
      },
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      },
      "title": "Active SIDs",
      "type": "splunk.singlevalue"
    },
    "viz_kpi_errors": {
      "dataSources": {
        "primary": "ds_disp_errors"
      },
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#dc4e41",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      },
      "title": "Dispatcher Errors",
      "type": "splunk.singlevalue"
    },
    "viz_kpi_functions": {
      "dataSources": {
        "primary": "ds_wp_functions_dc"
      },
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      },
      "title": "Active WP Functions",
      "type": "splunk.singlevalue"
    },
    "viz_category_trend": {
      "dataSources": {
        "primary": "ds_category_trend"
      },
      "options": {
        "backgroundColor": "transparent",
        "dataValuesDisplay": "off",
        "legendDisplay": "bottom",
        "legendTruncation": "ellipsisEnd",
        "seriesColors": [
          "#00d4b4",
          "#9c6aff",
          "#7ee8fa",
          "#f4a535",
          "#5ac8fa",
          "#4cd964",
          "#dc4e41",
          "#34aadc",
          "#b97bff",
          "#ffcc00",
          "#32ade6",
          "#ff9500",
          "#dc4e41",
          "#dc4e41"
        ],
        "stackMode": "stacked",
        "xAxisLabelVisibility": "auto",
        "xAxisTitleVisibility": "hide",
        "yAxisLabelVisibility": "auto",
        "yAxisTitleVisibility": "hide"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Work Process Category Trend",
      "type": "splunk.column"
    },
    "viz_category_mix": {
      "dataSources": {
        "primary": "ds_category_mix"
      },
      "options": {
        "backgroundColor": "transparent",
        "innerRadius": 0.6,
        "legendDisplay": "right",
        "legendTruncation": "ellipsisEnd",
        "seriesColors": [
          "#00d4b4",
          "#9c6aff",
          "#7ee8fa",
          "#f4a535",
          "#5ac8fa",
          "#4cd964",
          "#dc4e41",
          "#34aadc",
          "#b97bff",
          "#ffcc00",
          "#32ade6",
          "#ff9500",
          "#dc4e41",
          "#dc4e41"
        ]
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Category Distribution",
      "type": "splunk.pie"
    },
    "viz_top_functions": {
      "dataSources": {
        "primary": "ds_top_functions"
      },
      "options": {
        "backgroundColor": "transparent",
        "legendDisplay": "bottom",
        "xAxisLabelVisibility": "show",
        "yAxisLabelVisibility": "auto",
        "xAxisTitleVisibility": "hide",
        "overlayFields": [],
        "seriesColors": [
          "#00d4b4"
        ],
        "xAxisMajorTickVisibility": "show",
        "xAxisMajorTickSize": 2,
        "yAxisTitleVisibility": "hide"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Top Work Process Functions",
      "type": "splunk.bar"
    },
    "viz_severity_trend": {
      "dataSources": {
        "primary": "ds_severity_trend"
      },
      "options": {
        "backgroundColor": "transparent",
        "dataValuesDisplay": "off",
        "legendDisplay": "bottom",
        "seriesColors": [
          "#dc4e41",
          "#f4a535"
        ],
        "stackMode": "stacked",
        "xAxisLabelVisibility": "auto",
        "xAxisTitleVisibility": "hide",
        "yAxisLabelVisibility": "auto",
        "yAxisTitleVisibility": "hide"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Dispatcher Severity Over Time",
      "type": "splunk.column"
    },
    "viz_by_sid": {
      "dataSources": {
        "primary": "ds_by_sid"
      },
      "eventHandlers": [
        {
          "options": {
            "newTab": true,
            "url": "/app/search/search?q=%60sap_logserv_idx_macro%60%20sourcetype%3D%22sap%3Aabap%3Aworkprocess%22%20sap_sid%3D%22$row.SID.value$%22%20%7C%20stats%20count%20by%20wp_category_name%20wp_function%20sap_instance%20host%20%7C%20sort%20-count&earliest=$global_time.earliest$&latest=$global_time.latest$"
          },
          "type": "drilldown.customUrl"
        }
      ],
      "options": {
        "backgroundColor": "transparent",
        "count": 5,
        "dataOverlayMode": "none",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Activity by SID / Instance",
      "type": "splunk.table"
    },
    "viz_recent_errors": {
      "dataSources": {
        "primary": "ds_recent_errors"
      },
      "eventHandlers": [
        {
          "options": {
            "newTab": true,
            "url": "/app/search/search?q=%60sap_logserv_idx_macro%60%20sourcetype%3D%22sap%3Aabap%3Adispatcher%22%20dp_severity%3D%22ERROR%22%20host%3D%22$row.host.value$%22%20%7C%20table%20_time%20dp_function%20dp_reason%20dp_severity%20sap_sid%20%7C%20sort%20-_time&earliest=$global_time.earliest$&latest=$global_time.latest$"
          },
          "type": "drilldown.customUrl"
        }
      ],
      "options": {
        "backgroundColor": "transparent",
        "count": 5,
        "dataOverlayMode": "none",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "title": "Recent Dispatcher Errors",
      "type": "splunk.table"
    },
    "viz_nav_go": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_nav_go"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/$nav_target$?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_more_info": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_more_info"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "https://splunk.github.io/splunk-sap-logserv/content/logserv-app/dashboards/applications/#work-process-performance",
            "newTab": true
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_wp_total": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:workprocess\" | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search",
      "name": "sap_workprocess_events"
    },
    "ds_wp_sids": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:workprocess\" | eventstats dc(sap_sid) as window_dc | timechart span=1d dc(sap_sid) as daily, max(window_dc) as total | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0, total=0 | fields _time daily total]",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search",
      "name": "sap_workprocess_active_sids"
    },
    "ds_disp_errors": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:dispatcher\" dp_severity=\"ERROR\" | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search",
      "name": "sap_dispatcher_errors"
    },
    "ds_wp_functions_dc": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:workprocess\" wp_function=* | eventstats dc(wp_function) as window_dc | timechart span=1d dc(wp_function) as daily, max(window_dc) as total | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0, total=0 | fields _time daily total]",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search",
      "name": "sap_workprocess_functions"
    },
    "ds_category_trend": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:workprocess\" wp_category_name=* | timechart span=1d count by wp_category_name limit=14",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search",
      "name": "sap_work_process_category_trend"
    },
    "ds_category_mix": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:workprocess\" wp_category_name=* | stats count by wp_category_name | sort -count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search",
      "name": "sap_category_distribution"
    },
    "ds_top_functions": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:workprocess\" wp_function=* | stats count by wp_function | sort -count | head 15 | rename wp_function as \"Function\", count as \"Events\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search",
      "name": "top_workprocess_functions"
    },
    "ds_severity_trend": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:dispatcher\" dp_severity=* | timechart span=1d count by dp_severity",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search",
      "name": "sap_dispatcher_severity_over_time"
    },
    "ds_by_sid": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:workprocess\" | stats count as \"Total Events\", dc(wp_function) as \"Unique Functions\", dc(wp_category_name) as \"WP Categories\" by sap_sid, sap_instance | sort -\"Total Events\" | rename sap_sid as \"SID\", sap_instance as \"Instance\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search",
      "name": "sap_workprocess_activity_by_sid"
    },
    "ds_recent_errors": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:dispatcher\" dp_severity=\"ERROR\" | fillnull value=\"-\" dp_function dp_reason | eval Time=strftime(_time, \"%Y-%m-%d %H:%M:%S\") | table Time, sap_sid, dp_function, dp_reason, host | sort -Time | head 25 | rename sap_sid as \"SID\", dp_function as \"Function\", dp_reason as \"Reason\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "type": "ds.search",
      "name": "sap_dispatcher_recent_errors"
    },
    "ds_nav_go": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"Go >\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    },
    "ds_more_info": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"More Info\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_global_trp",
      "input_nav_dropdown"
    ],
    "layoutDefinitions": {
      "layout_1": {
        "options": {
          "backgroundColor": "#0d1117",
          "height": 1330,
          "width": 1920,
          "display": "fit-to-width"
        },
        "structure": [
          {
            "item": "viz_nav_go",
            "type": "block",
            "position": {
              "x": 10,
              "y": 10,
              "w": 120,
              "h": 25
            }
          },
          {
